    /// <c>table_function_statistics</c> RPC. Bytes are the IPC payload from
    /// <c>serialize_column_statistics(stats, cache_max_age_seconds)</c>. Freezes the resolved stats for
    /// the catalog cache lifetime (until <c>catalog_version</c> bumps); workers whose statistics change
    /// faster than <c>catalog_version</c> (e.g. live counters, rapidly-mutating dimensions) MUST leave
    /// this null so the on-demand RPC continues to fire.
    /// </summary>
    public byte[]? ColumnStatistics { get; set; }

    /// <summary>
    /// Optional inlined bind result. Bytes are the IPC payload of
    /// <c>BindResponse.serialize_to_bytes()</c>. When populated, the C++ extension uses these bytes
    /// verbatim and skips the per-scan <c>bind</c> RPC, threading the deserialized BindResult straight
    /// into bind_data. The catalog framework only populates this for tables marked
    /// <c>Table(inline_bind=True)</c> whose function class is <c>@bind_fixed_schema</c>-decorated — the
    /// decorator's contract (output is exactly <c>cls.FIXED_SCHEMA</c>, no per-call inputs, no
    /// opaque_data) matches what's safe to freeze for the catalog cache lifetime. Functions with custom
    /// <c>on_bind</c> are not eligible via the framework path; workers can still inline manually inside
    /// their own <c>schema_contents</c> override when the bind output is independently known to be
    /// stable.
    /// </summary>
    public byte[]? BindResult { get; set; }

    /// <summary>
    /// Required WHERE-filter groups the VGI extension's optimizer pass verifies against any scan
    /// (conjunctive normal form): the outer list is an AND of groups, each inner group is an OR of
    /// dotted-path column references (top-level names like <c>"country"</c> or struct subfields like
    /// <c>"bbox.xmin"</c>). A group is satisfied when any one of its paths has a filter; every group
    /// must be satisfied. So <c>[["accession_number"], ["ticker", "cik"]]</c> means "accession_number
    /// AND one of (ticker, cik)". Empty (default) means no enforcement — the zero-cost fast path.
    /// Satisfaction is prefix-based: a present filter on a shorter dotted path satisfies any required
    /// path it's a prefix of (a whole-struct filter on <c>bbox</c> satisfies every <c>"bbox.*"</c>
    /// path). The C++ extension throws <c>BinderException</c> listing any unsatisfied groups.
    /// </summary>
    public global::System.Collections.Generic.List<global::System.Collections.Generic.List<string>> RequiredFilters { get; set; } = [];
}

/// <summary>
/// Response wrapping optional <c>TransactionOpaqueData</c> for <c>catalog_transaction_begin()</c>.
/// </summary>
/// <remarks>Protocol type: method 'catalog_transaction_begin' result.</remarks>
public sealed partial class TransactionBeginResponse
{
    /// <summary>
    /// Opaque DuckDB transaction handle (bytes) for the newly begun transaction; <c>None</c> when the
    /// worker is non-transactional.
    /// </summary>
    public byte[]? TransactionOpaqueData { get; set; }
}

/// <summary>
/// Information about a view in a schema.
/// </summary>
/// <remarks>Protocol type: ViewInfo.</remarks>
public sealed partial class ViewInfo
{
    public string? Comment { get; set; }

    public global::System.Collections.Generic.Dictionary<string, string> Tags { get; set; } = [];

    public string Name { get; set; } = "";

    public global::System.Collections.Generic.List<string> SchemaPath { get; set; } = [];

    /// <summary>
    /// The definition of the view which is a SQL query string.
    /// </summary>
    public string Definition { get; set; } = "";

    /// <summary>
    /// Per-column comments, keyed by the view's output column name. Unlike tables (whose column
    /// comments ride along as Arrow field metadata on the serialized <c>columns</c> schema), a view
    /// ships only its SQL <c>definition</c> — DuckDB binds that query to derive the columns — so view
    /// column comments need their own channel. The C++ extension aligns these by name against the bound
    /// output columns and feeds them into <c>CreateViewInfo.column_comments_map</c>; names that don't
    /// match a bound column are ignored.
    /// </summary>
    public global::System.Collections.Generic.Dictionary<string, string> ColumnComments { get; set; } = [];
}
